WITH lines AS (SELECT id, effective_from, val FROM price_tiers LATERAL VIEW OUTER EXPLODE(tier_prices) li AS val), base AS (SELECT *, DATEDIFF(CURRENT_DATE(), effective_from) / 365.25 AS years_since_effective_from FROM lines WHERE effective_from > TO_DATE('2024-06-20') AND YEAR(effective_from) = 2025), remaining_keys AS (SELECT id FROM base EXCEPT ALL SELECT id FROM price_tiers WHERE effective_from < '2025-08-25'), reconciled AS (SELECT s.* FROM base s JOIN remaining_keys k ON s.id = k.id), metrics AS (SELECT id, effective_from, val, PERCENT_RANK() OVER (ORDER BY years_since_effective_from DESC NULLS FIRST) AS years_since_effective_from_percent_rank FROM reconciled), filtered AS (SELECT *, FLOOR(years_since_effective_from_percent_rank) AS years_since_effective_from_percent_rank_whole FROM metrics WHERE val < 75), valid AS (SELECT effective_from, val, years_since_effective_from_percent_rank, years_since_effective_from_percent_rank_whole, COALESCE(years_since_effective_from_percent_rank_whole, 0) AS years_since_effective_from_percent_rank_whole_filled FROM filtered WHERE effective_from > '2025-06-01'), cleaned AS (SELECT *, DATE_ADD(effective_from, 6) AS effective_from_plus_6d FROM valid WHERE YEAR(effective_from) = 2024), report AS (SELECT effective_from, years_since_effective_from_percent_rank, years_since_effective_from_percent_rank_whole, years_since_effective_from_percent_rank_whole_filled, effective_from_plus_6d FROM cleaned ORDER BY effective_from NULLS FIRST) SELECT years_since_effective_from_percent_rank, years_since_effective_from_percent_rank_whole, years_since_effective_from_percent_rank_whole_filled, effective_from_plus_6d FROM report ORDER BY effective_from_plus_6d DESC NULLS LAST
